import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 998244353;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        long l = Long.parseLong(st.nextToken());

        int max = 2 * n + 5;

        int[] inv = new int[max];
        inv[1] = 1;
        for (int i = 2; i < max; i++) {
            inv[i] = MOD - (int)((long)(MOD / i) * inv[MOD % i] % MOD);
        }

        int[] powInv2 = new int[max];
        powInv2[0] = 1;
        int inv2 = (MOD + 1) / 2;
        for (int i = 1; i < max; i++) {
            powInv2[i] = (int)((long)powInv2[i - 1] * inv2 % MOD);
        }

        int[][] C = new int[max][max];
        for (int i = 0; i < max; i++) {
            C[i][0] = C[i][i] = 1;
            for (int j = 1; j < i; j++) {
                C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
                if (C[i][j] >= MOD) C[i][j] -= MOD;
            }
        }

        int[][] fact = new int[max][max];
        for (int i = 0; i < max; i++) {
            fact[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                fact[i][j] = (int)((long)fact[i][j - 1] * j % MOD);
            }
        }

        long ans = 0;
        for (int i = k; i <= n; i++) {
            int sign = (i - k) % 2 == 0 ? 1 : MOD - 1;
            long term = sign;
            term = term * C[i - 1][k - 1] % MOD;
            term = term * C[n][i] % MOD;
            term = term * fact[i][i] % MOD; // i!
            term = term * powInv2[i] % MOD;
            term = term * inv[2 * i + 1] % MOD;
            ans = (ans + term) % MOD;
        }

        ans = ans * (l % MOD) % MOD;
        System.out.println(ans);
    }
}
